public async Task Sends_report_every_5_minutes()
{
    var time = new FakeTimeProvider(DateTimeOffset.Parse("2026-01-10T08:00Z"));
    var sender = new FakeReportSender();
    var worker = new ReportWorker(sender, time);

    await worker.StartAsync(CancellationToken.None);
    await sender.WaitingForDelay;            // worker doszedł do Task.Delay

    time.Advance(TimeSpan.FromMinutes(5));
    await sender.FirstReport.WaitAsync(TimeSpan.FromSeconds(2));
    Assert.Equal(1, sender.Count);
}

