public sealed class OrderBuilder
{
    private CustomerId _customer = CustomerId.New();
    private readonly List<(string Sku, int Qty, decimal Price)> _lines = [("SKU-1", 1, 10m)];
    private bool _paid;

    public OrderBuilder For(CustomerId c) { _customer = c; return this; }
    public OrderBuilder WithLine(string sku, int qty, decimal price) { _lines.Add((sku, qty, price)); return this; }
    public OrderBuilder Paid() { _paid = true; return this; }

    public Order Build()
    {
        var order = Order.Create(_customer);
        foreach (var l in _lines) order.AddLine(l.Sku, l.Qty, l.Price);
        if (_paid) order.MarkPaid(DateTimeOffset.UnixEpoch);
        return order;
    }
}

