export class QuantityHarness extends ComponentHarness {
  static hostSelector = 'app-quantity';
  private input = this.locatorFor('input');
  private plus = this.locatorFor('button.plus');

  async getValue() { return Number(await (await this.input()).getProperty('value')); }
  async increment() { await (await this.plus()).click(); }
}

